<?php
/** @var \App\Moderation\SocialReport $report */
$date = static function (?string $value): string { if ($value === null) { return '—'; } try { return (new DateTimeImmutable($value))->format('d/m/Y H:i'); } catch (Throwable) { return $value; } };
$selectedDuration = is_string($selectedDuration ?? null) ? $selectedDuration : '';
$sanctionErrors = is_array($sanctionErrors ?? null) ? $sanctionErrors : [];
$sanctionNote = is_string($sanctionNote ?? null) ? $sanctionNote : '';
?>
<section class="admin-report" aria-labelledby="admin-report-title">
    <?php foreach (($messages['success'] ?? []) as $message): ?><p class="form-alert form-alert--success" role="status"><?= e((string) $message) ?></p><?php endforeach; ?>
    <a class="report-page__back" href="/admin/denuncias">← Voltar à fila</a>
    <header class="admin-report__header"><div><p class="eyebrow">Moderação · denúncia #<?= $report->id ?></p><h1 id="admin-report-title"><?= e($report->targetType->label()) ?> denunciado</h1></div><span class="report-status report-status--<?= e($report->status->value) ?>"><?= e($report->status->label()) ?></span></header>
    <div class="admin-report__grid">
        <section class="admin-report__panel"><h2>Registro</h2><dl><div><dt>Motivo</dt><dd><?= e($report->reason->label()) ?></dd></div><div><dt>Reporter</dt><dd>@<?= e($report->reporterUsername) ?></dd></div><div><dt>Usuário denunciado</dt><dd><?= e($report->targetDisplayName ?? 'Indisponível') ?><?= $report->targetUsername !== null ? ' · @' . e($report->targetUsername) : '' ?></dd></div><div><dt>Enviada em</dt><dd><?= e($date($report->createdAt)) ?></dd></div></dl><?php if (($targetUser ?? null) instanceof \App\Moderation\ModeratedUser): ?><a class="admin-inline-link" href="/admin/usuarios/<?= e(rawurlencode($targetUser->username)) ?>">Ver estado administrativo do usuário →</a><?php endif; ?></section>
        <section class="admin-report__panel"><h2>Detalhes fornecidos</h2><p class="admin-report__text"><?= $report->details !== null ? nl2br(e($report->details)) : 'Nenhum detalhe adicional.' ?></p></section>
        <section class="admin-report__panel admin-report__panel--snapshot"><h2>Snapshot preservado</h2><p class="admin-report__text"><?= $report->contentSnapshot !== null && $report->contentSnapshot !== '' ? nl2br(e($report->contentSnapshot)) : 'O alvo não possuía texto no momento da denúncia.' ?></p></section>
        <?php if ($report->status !== \App\Moderation\ReportStatus::Pending): ?><section class="admin-report__panel"><h2>Revisão encerrada</h2><dl><div><dt>Data</dt><dd><?= e($date($report->reviewedAt)) ?></dd></div><div><dt>Nota interna</dt><dd><?= $report->moderatorNote !== null ? nl2br(e($report->moderatorNote)) : 'Sem nota.' ?></dd></div></dl></section><?php endif; ?>
    </div>
    <?php if ($report->status === \App\Moderation\ReportStatus::Pending): ?>
    <div class="admin-decision-grid">
        <section class="admin-review" aria-labelledby="admin-review-title"><p class="eyebrow">Classificação</p><h2 id="admin-review-title">Encerrar sem sanção</h2><p>Resolve ou arquiva a denúncia sem alterar conta ou conteúdo.</p><form method="post" novalidate><?= $csrf->field() ?><div class="profile-field"><label for="moderator-note">Nota interna <span>(opcional)</span></label><textarea id="moderator-note" name="moderator_note" rows="5" maxlength="1000" aria-describedby="moderator-note-hint<?= isset($errors['moderator_note']) ? ' moderator-note-error' : '' ?>"<?= isset($errors['moderator_note']) ? ' aria-invalid="true"' : '' ?>><?= e($note) ?></textarea><p id="moderator-note-hint">Visível somente na área administrativa.</p><?php if (isset($errors['moderator_note'])): ?><p class="profile-field__error" id="moderator-note-error" role="alert"><?= e((string) $errors['moderator_note']) ?></p><?php endif; ?></div><div class="admin-review__actions"><button class="button button--primary" type="submit" formaction="/admin/denuncias/<?= $report->id ?>/resolver">Resolver sem ação</button><button class="button button--secondary" type="submit" formaction="/admin/denuncias/<?= $report->id ?>/arquivar">Arquivar</button></div></form></section>

        <?php if (($targetUser ?? null) instanceof \App\Moderation\ModeratedUser && !$targetUser->isAdmin && $targetUser->id !== $auth->id()): ?>
        <section class="admin-review admin-review--sanction" aria-labelledby="suspend-title"><p class="eyebrow">Sanção temporária</p><h2 id="suspend-title">Suspender conta</h2><p>A conta perderá acesso no próximo request. Conteúdo e relações sociais permanecem.</p><form method="post" action="/admin/denuncias/<?= $report->id ?>/suspender" novalidate><?= $csrf->field() ?><fieldset class="duration-options"<?= isset($sanctionErrors['duration']) ? ' aria-describedby="duration-error"' : '' ?>><legend>Duração</legend><?php foreach ($durations as $duration): ?><label><input type="radio" name="duration" value="<?= e($duration->value) ?>"<?= $selectedDuration === $duration->value ? ' checked' : '' ?>><span><?= e($duration->label()) ?></span></label><?php endforeach; ?></fieldset><?php if (isset($sanctionErrors['duration'])): ?><p class="profile-field__error" id="duration-error" role="alert"><?= e($sanctionErrors['duration']) ?></p><?php endif; ?><div class="profile-field"><label for="sanction-note">Nota administrativa <span>(obrigatória)</span></label><textarea id="sanction-note" name="moderator_note" rows="5" maxlength="1000" aria-describedby="sanction-note-hint<?= isset($sanctionErrors['moderator_note']) ? ' sanction-note-error' : '' ?>"<?= isset($sanctionErrors['moderator_note']) ? ' aria-invalid="true"' : '' ?>><?= e($sanctionNote) ?></textarea><p id="sanction-note-hint">Entre 10 e 1000 caracteres. Privada e auditável.</p><?php if (isset($sanctionErrors['moderator_note'])): ?><p class="profile-field__error" id="sanction-note-error" role="alert"><?= e($sanctionErrors['moderator_note']) ?></p><?php endif; ?></div><button class="button button--danger" type="submit">Suspender temporariamente</button></form></section>
        <?php elseif (($targetUser ?? null) instanceof \App\Moderation\ModeratedUser && $targetUser->isAdmin): ?><section class="admin-review"><p class="eyebrow">Conta protegida</p><h2>Administrador</h2><p>Contas administrativas não podem ser suspensas pela aplicação web. A denúncia ainda pode ser resolvida ou arquivada.</p></section><?php endif; ?>

        <?php if ($report->targetType === \App\Moderation\ReportTargetType::Comment && ($commentLive ?? false) === true): ?><section class="admin-review admin-review--danger" aria-labelledby="remove-comment-title"><p class="eyebrow">Ação sobre conteúdo</p><h2 id="remove-comment-title">Remover comentário denunciado</h2><p>Remove somente este comentário, preserva a atividade e resolve a denúncia. A ação fica auditada.</p><form method="post" action="/admin/denuncias/<?= $report->id ?>/remover-comentario" novalidate><?= $csrf->field() ?><div class="profile-field"><label for="remove-note">Nota administrativa <span>(obrigatória)</span></label><textarea id="remove-note" name="moderator_note" rows="5" maxlength="1000" aria-describedby="remove-note-hint<?= isset($sanctionErrors['moderator_note']) ? ' remove-note-error' : '' ?>"<?= isset($sanctionErrors['moderator_note']) ? ' aria-invalid="true"' : '' ?>><?= e($sanctionNote) ?></textarea><p id="remove-note-hint">Entre 10 e 1000 caracteres. O comentário será removido definitivamente.</p><?php if (isset($sanctionErrors['moderator_note'])): ?><p class="profile-field__error" id="remove-note-error" role="alert"><?= e($sanctionErrors['moderator_note']) ?></p><?php endif; ?></div><button class="button button--danger" type="submit">Remover comentário e resolver</button></form></section><?php endif; ?>
    </div>
    <?php endif; ?>
</section>
